import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import Layout from './components/layout/Layout';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Staff from './pages/Staff';
import Returns from './pages/Returns';
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import Login from './pages/Login';
import WorkerDashboard from './pages/WorkerDashboard';
import './styles/index.css';

// Protected route component
const ProtectedRoute = ({ children, allowedRoles }) => {
  const { user, loading, isAuthenticated } = useAuth();

  if (loading) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        background: '#f3f4f6'
      }}>
        <div className="loading"></div>
      </div>
    );
  }

  if (!isAuthenticated()) {
    return <Navigate to="/login" replace />;
  }

  // Validaci├│n de roles desactivada a petici├│n del usuario.
  // if (allowedRoles && !allowedRoles.includes(user?.role)) {
  //   // Redirect to appropriate dashboard based on role
  //   if (user?.role === 'worker') {
  //     return <Navigate to="/worker" replace />;
  //   }
  //   return <Navigate to="/" replace />;
  // }

  return children;
};

// App routes component
const AppRoutes = () => {
  const { isAuthenticated, user } = useAuth();

  return (
    <Routes>
      {/* Public route - Login */}
      <Route
        path="/login"
        element={
          isAuthenticated() ? (
            <Navigate to={user?.role === 'worker' ? '/worker' : '/'} replace />
          ) : (
            <Login />
          )
        }
      />

      {/* Admin routes */}
      <Route
        path="/"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Panel de Control General" subtitle="M├®tricas de inventario y reportes en tiempo real.">
              <Dashboard />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/inventario"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Inventario" subtitle="Gesti├│n de existencias y categor├¡as.">
              <Inventory />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/personal"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Personal" subtitle="Gesti├│n de empleados y asignaciones.">
              <Staff />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/devoluciones"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Devoluciones" subtitle="Gesti├│n de devoluciones de uniformes.">
              <Returns />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/devoluciones/:employeeId"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Devoluciones" subtitle="Gesti├│n de devoluciones de uniformes.">
              <Returns />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/reportes"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Reportes" subtitle="An├ílisis y reportes detallados.">
              <Reports />
            </Layout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/inventario-rfid"
        element={<Navigate to="/inventario" replace />}
      />
      <Route
        path="/configuracion"
        element={
          <ProtectedRoute allowedRoles={['admin']}>
            <Layout title="Configuraci├│n" subtitle="Preferencias y ajustes del sistema.">
              <Settings />
            </Layout>
          </ProtectedRoute>
        }
      />

      {/* Worker routes */}
      <Route
        path="/worker"
        element={
          <ProtectedRoute allowedRoles={['worker', 'admin']}>
            <WorkerDashboard />
          </ProtectedRoute>
        }
      />

      {/* Fallback */}
      <Route path="*" element={<Navigate to="/login" replace />} />
    </Routes>
  );
};

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;

