import { useState, useEffect, useRef, useCallback } from 'react';
import { huellasService } from '../../services/huellasService';
import './FingerprintControl.css';

const POLLING_INTERVAL = 500; // ms

/**
 * Componente reutilizable para control del lector de huellas.
 *
 * Props:
 * - mode: 'identification' | 'registration'
 * - rut: (solo registration) RUT del empleado a enrolar
 * - onScanSuccess: (data) => void ÔÇö callback al identificar exitosamente
 * - onRegisterSuccess: (data) => void ÔÇö callback al completar enrolamiento
 */
const FingerprintControl = ({ mode = 'identification', rut, onScanSuccess, onRegisterSuccess }) => {
    const [readerStatus, setReaderStatus] = useState({ conectado: false, ocupado: false });
    const [sessionId, setSessionId] = useState(null);
    const [sessionState, setSessionState] = useState(null);
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(false);

    const pollingRef = useRef(null);
    const mountedRef = useRef(true);

    const checkReaderStatus = async () => {
        try {
            const data = await huellasService.getReaderStatus();
            if (mountedRef.current) setReaderStatus(data);
        } catch {
            if (mountedRef.current) setReaderStatus({ conectado: false, ocupado: false });
        }
    };

    const stopPolling = () => {
        if (pollingRef.current) {
            clearInterval(pollingRef.current);
            pollingRef.current = null;
        }
    };

    // Cleanup al montar
    useEffect(() => {
        mountedRef.current = true;
        checkReaderStatus();
        return () => {
            mountedRef.current = false;
            stopPolling();
            // Cancelar sesi├│n activa si hay una
            if (sessionId) {
                huellasService.cancelarSesion(sessionId).catch(() => {});
            }
        };
    }, [sessionId]);

    // --- Polling ---
    const startPolling = useCallback((sid) => {
        stopPolling();
        pollingRef.current = setInterval(async () => {
            if (!mountedRef.current) { stopPolling(); return; }
            try {
                const estado = await huellasService.obtenerEstado(sid);
                if (!mountedRef.current) return;

                setSessionState(estado);

                if (estado.status === 'completado') {
                    stopPolling();
                    if (mode === 'identification' && estado.resultado) {
                        onScanSuccess?.(estado.resultado);
                    } else if (mode === 'identification' && !estado.resultado) {
                        setError('Huella no reconocida. Intente nuevamente.');
                    }
                    if (mode === 'registration' && estado.resultado) {
                        // Guardar template en backend (BD) via guardarHuella
                        if (rut && estado.resultado.template) {
                            try {
                                await huellasService.guardarHuella(rut, estado.resultado.template);
                            } catch (saveErr) {
                                setError('Captura exitosa pero error al guardar: ' + (saveErr.message || 'Error desconocido'));
                                setLoading(false);
                                return;
                            }
                        }
                        onRegisterSuccess?.(estado.resultado);
                    }
                    setLoading(false);
                } else if (estado.status === 'error') {
                    stopPolling();
                    setError(estado.error || 'Error durante la captura');
                    setLoading(false);
                } else if (estado.status === 'cancelado') {
                    stopPolling();
                    setLoading(false);
                }
            } catch (err) {
                // Sesi├│n expirada o no encontrada
                stopPolling();
                if (mountedRef.current) {
                    setError('Sesi├│n expirada');
                    setLoading(false);
                }
            }
        }, POLLING_INTERVAL);
    }, [mode, onScanSuccess, onRegisterSuccess]);

    // --- Iniciar identificaci├│n ---
    const handleIdentify = async () => {
        setError(null);
        setSessionState(null);
        setLoading(true);
        try {
            // 1. Obtener templates desde el backend
            const templates_data = await huellasService.getTemplates();
            if (!templates_data || templates_data.length === 0) {
                setError('No hay huellas registradas en el sistema');
                setLoading(false);
                return;
            }
            // 2. Enviar templates al middleware para captura + comparaci├│n
            const { session_id } = await huellasService.iniciarIdentificacion(templates_data);
            if (!mountedRef.current) return;
            setSessionId(session_id);
            startPolling(session_id);
        } catch (err) {
            if (!mountedRef.current) return;
            const msg = err?.response?.data?.detail || err.message || 'Error al iniciar identificaci├│n';
            setError(msg);
            setLoading(false);
        }
    };

    // --- Iniciar enrolamiento ---
    const handleEnroll = async () => {
        if (!rut) { setError('RUT requerido para enrolamiento'); return; }
        setError(null);
        setSessionState(null);
        setLoading(true);
        try {
            // Middleware solo captura, no necesita rut
            const { session_id } = await huellasService.iniciarEnrolamiento();
            if (!mountedRef.current) return;
            setSessionId(session_id);
            startPolling(session_id);
        } catch (err) {
            if (!mountedRef.current) return;
            const msg = err?.response?.data?.detail || err.message || 'Error al iniciar enrolamiento';
            setError(msg);
            setLoading(false);
        }
    };

    // --- Cancelar ---
    const handleCancel = async () => {
        if (sessionId) {
            try { await huellasService.cancelarSesion(sessionId); } catch {}
        }
        stopPolling();
        setSessionId(null);
        setSessionState(null);
        setLoading(false);
    };

    // --- Reintentar ---
    const handleRetry = () => {
        setError(null);
        setSessionState(null);
        setSessionId(null);
    };

    // --- UI helpers ---
    const isActive = loading && sessionState &&
        (sessionState.status === 'esperando_dedo' || sessionState.status === 'procesando');

    const isCompleted = sessionState?.status === 'completado';
    const isError = sessionState?.status === 'error' || error;

    // Render de pasos de enrolamiento
    const renderEnrollmentProgress = () => {
        if (mode !== 'registration' || !sessionState) return null;
        const total = sessionState.pasos_total || 4;
        const current = sessionState.paso_actual || 1;

        return (
            <div className="fp-enrollment-progress">
                <div className="fp-steps">
                    {Array.from({ length: total }, (_, i) => {
                        const stepNum = i + 1;
                        let stepClass = 'fp-step pending';
                        if (isCompleted || stepNum < current) {
                            stepClass = 'fp-step completed';
                        } else if (stepNum === current && isActive) {
                            stepClass = 'fp-step active';
                        }
                        return (
                            <div key={i} className={stepClass}>
                                <div className="fp-step-icon">
                                    {(isCompleted || stepNum < current) ? (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                                            <path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" fill="currentColor"/>
                                        </svg>
                                    ) : (
                                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                            <path d="M12 11c0-1.1-.9-2-2-2s-2 .9-2 2 .9 2 2 2 2-.9 2-2z"/>
                                            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8 0-1.85.63-3.55 1.69-4.9L16.9 18.31C15.55 19.37 13.85 20 12 20z"/>
                                        </svg>
                                    )}
                                </div>
                                <span className="fp-step-label">{stepNum}</span>
                            </div>
                        );
                    })}
                </div>
                {isActive && (
                    <p className="fp-step-text">Captura {current} de {total} ÔÇö Coloque el dedo</p>
                )}
            </div>
        );
    };

    return (
        <div className="fingerprint-control-card">
            {/* Status del lector */}
            <div className={`fp-status-indicator ${readerStatus.conectado ? 'connected' : 'disconnected'}`}>
                <span className="status-dot"></span>
                <span className="status-text">
                    {readerStatus.conectado ? 'Lector Conectado' : 'Lector Desconectado'}
                </span>
            </div>

            {/* Icono visual */}
            <div className="fp-visual-area">
                <div className={`fp-icon-container ${isActive ? 'scanning' : ''} ${isCompleted ? 'success' : ''} ${isError ? 'error' : ''}`}>
                    <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M12 10a2 2 0 00-2 2c0 1.02.76 2 2 2s2-.98 2-2a2 2 0 00-2-2z"/>
                        <path d="M12 2C9.24 2 7 4.24 7 7v2a5 5 0 0010 0V7c0-2.76-2.24-5-5-5z"/>
                        <path d="M17 13a5 5 0 01-10 0"/>
                        <path d="M19 15a7 7 0 01-14 0"/>
                        <path d="M21 17a9 9 0 01-18 0"/>
                    </svg>
                </div>
            </div>

            {/* Progreso de enrolamiento */}
            {renderEnrollmentProgress()}

            {/* Acciones */}
            <div className="fp-actions">
                {!loading && !isCompleted && !error && (
                    <button
                        className={`fp-btn ${mode === 'registration' ? 'btn-scan btn-register' : 'btn-scan btn-identify'}`}
                        onClick={mode === 'registration' ? handleEnroll : handleIdentify}
                        disabled={!readerStatus.conectado || readerStatus.ocupado}
                    >
                        {mode === 'registration' ? 'Enrolar Huella' : 'Identificar con Huella'}
                    </button>
                )}

                {isActive && (
                    <button className="fp-btn btn-cancel" onClick={handleCancel}>
                        Cancelar
                    </button>
                )}

                {(isCompleted || error) && (
                    <button className="fp-btn btn-connect" onClick={handleRetry}>
                        {error ? 'Reintentar' : 'Nueva operaci├│n'}
                    </button>
                )}
            </div>

            {/* Estado textual */}
            {isActive && !error && (
                <div className="fp-hardware-message">
                    <small>
                        {sessionState?.status === 'procesando'
                            ? 'Procesando huella...'
                            : 'Esperando dedo en el lector...'}
                    </small>
                </div>
            )}

            {/* Resultado exitoso */}
            {isCompleted && sessionState.resultado && mode === 'identification' && (
                <div className="fp-result-message success">
                    Identificado: {sessionState.resultado.nombre_completo}
                </div>
            )}
            {isCompleted && sessionState.resultado && mode === 'registration' && (
                <div className="fp-result-message success">
                    Huella registrada exitosamente
                </div>
            )}
            {isCompleted && !sessionState.resultado && mode === 'identification' && (
                <div className="fp-result-message warning">
                    Huella no reconocida
                </div>
            )}

            {/* Error */}
            {error && <div className="fp-error-message">{error}</div>}
        </div>
    );
};

export default FingerprintControl;

