import { useState, useEffect } from 'react';

const CatalogoModal = ({ titulo, valorInicial = '', onGuardar, onCerrar, guardando, errorServidor }) => {
    const [nombre, setNombre] = useState(valorInicial);
    const [errorLocal, setErrorLocal] = useState('');

    useEffect(() => {
        setNombre(valorInicial);
        setErrorLocal('');
    }, [valorInicial]);

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!nombre.trim()) {
            setErrorLocal('El nombre no puede estar vac├¡o');
            return;
        }
        setErrorLocal('');
        onGuardar(nombre.trim());
    };

    return (
        <div className="modal-overlay" onClick={onCerrar}>
            <div className="modal-box" onClick={(e) => e.stopPropagation()}>
                <h3 className="modal-title">{titulo}</h3>

                <form onSubmit={handleSubmit}>
                    <div className="modal-field">
                        <label className="modal-label">Nombre</label>
                        <input
                            className="modal-input"
                            type="text"
                            value={nombre}
                            onChange={(e) => setNombre(e.target.value)}
                            autoFocus
                            disabled={guardando}
                            placeholder="Ingresa el nombre..."
                        />
                        {errorLocal && (
                            <p className="modal-error">{errorLocal}</p>
                        )}
                        {errorServidor && (
                            <p className="modal-error">{errorServidor}</p>
                        )}
                    </div>

                    <div className="modal-actions">
                        <button
                            type="button"
                            className="catalogo-btn catalogo-btn--cancel"
                            onClick={onCerrar}
                            disabled={guardando}
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            className="catalogo-btn catalogo-btn--primary"
                            disabled={guardando}
                        >
                            {guardando ? 'Guardando...' : 'Guardar'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CatalogoModal;

import { useNavigate } from 'react-router-dom';
import './EmployeeRow.css';

const EmployeeRow = ({ employee, onEdit, onRegisterFingerprint }) => {
    const navigate = useNavigate();

    const getInitials = (name) => {
        const parts = name.split(' ');
        if (parts.length >= 2) {
            return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
        }
        return name.substring(0, 2).toUpperCase();
    };

    return (
        <tr className="employee-row">
            <td className="employee-cell">
                <div className="employee-info">
                    <div className="employee-avatar">
                        {getInitials(employee.name)}
                    </div>
                    <div className="employee-details">
                        <div className="employee-name">{employee.name}</div>
                        <div className="employee-meta">
