                </div>
            </td>

            <td className="request-cell">{employee.cargo}</td>

            <td className="actions-cell">
                <button
                    className="action-btn fingerprint-btn"
                    onClick={() => onRegisterFingerprint(employee)}
                    title="Registrar Huella"
                >
                    ­ƒæå
                </button>
                <button
