import { useState, useEffect } from 'react';
import './BiometricScanner.css';

const BiometricScanner = ({ onVerify }) => {
    const [status, setStatus] = useState('scanning'); // scanning, detected, error
    const [matchPercentage, setMatchPercentage] = useState(0);
    const [animating, setAnimating] = useState(true);

    useEffect(() => {
        // Simulate biometric detection
        const timer = setTimeout(() => {
            setStatus('detected');
            setMatchPercentage(98.5);
            setAnimating(false);
        }, 2000);

        return () => clearTimeout(timer);
    }, []);

    const handleRecalibrate = () => {
        setStatus('scanning');
        setMatchPercentage(0);
        setAnimating(true);

        setTimeout(() => {
            setStatus('detected');
            setMatchPercentage(98.5);
            setAnimating(false);
        }, 2000);
    };

    return (
        <div className="biometric-scanner-card">
            <div className="scanner-header">
                <h3 className="scanner-title">Identificaci├│n Biom├®trica</h3>
                <span className="fingerprint-icon">­ƒæå</span>
            </div>

            <div className={`scanner-visual ${animating ? 'scanning' : ''}`}>
                <div className="fingerprint-circle">
                    <div className="fingerprint-icon-large">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10" />
                            <path d="M12 6c-3.31 0-6 2.69-6 6" />
                            <path d="M12 10c-1.1 0-2 .9-2 2" />
                            <path d="M22 12c0 5.52-4.48 10-10 10" />
                            <path d="M18 12c0 3.31-2.69 6-6 6" />
                            <path d="M14 12c0 1.1-.9 2-2 2" />
                        </svg>
                    </div>
                </div>
            </div>

            <div className="scanner-status">
                <p className="status-text">
                    {status === 'scanning' && 'Escaneando huella...'}
                    {status === 'detected' && 'Huella Detectada'}
                    {status === 'error' && 'Error de lectura'}
                </p>

                {status === 'detected' && (
                    <div className="match-info">
                        <span className="match-label">Nivel de coincidencia: {matchPercentage}%</span>
                        <div className="match-bar">
                            <div
                                className="match-progress"
                                style={{ width: `${matchPercentage}%` }}
                            />
                        </div>
                    </div>
                )}
            </div>

            <button className="recalibrate-btn" onClick={handleRecalibrate}>
                Recalibrar Sensor
            </button>
        </div>
    );
};

export default BiometricScanner;

import './ScanHistory.css';

const ScanHistory = ({ items, onEdit }) => {
    const getStatusColor = (status) => {
        switch (status?.toLowerCase()) {
            case 'buen estado':
                return 'status-good';
            case 'desgaste leve':
                return 'status-warning';
            case 'requiere reparaci├│n':
                return 'status-error';
            default:
                return '';
        }
    };

    const getItemIcon = (item) => {
        const icons = {
            'Chaleco Reflectante': '­ƒª║',
            'Casco Seguridad': 'Ôøæ´©Å',
            'Guantes T├®rmicos': '­ƒºñ',
            'Botas Seguridad': '­ƒÑ¥',
            'Gafas Protectoras': '­ƒÑ¢',
            'Overol': '­ƒæö'
        };
        return icons[item] || '­ƒæò';
    };

    return (
        <div className="scan-history-card">
            <div className="history-header">
                <div className="history-title-section">
                    <span className="history-icon">­ƒòÉ</span>
                    <h3 className="history-title">Historial en tiempo real</h3>
                </div>
                <span className="last-update">Actualizado ahora</span>
            </div>

            <div className="history-table-container">
                <table className="history-table">
                    <thead>
                                <tr>
                            <th>ITEM</th>
                            <th>TRABAJADOR</th>
                            <th>RUT</th>
                            <th>HORA ASIGNACI├ôN</th>
                            <th>HORA RECEPCI├ôN</th>
                        </tr>
                    </thead>
                    <tbody>
                        {items.map((item) => (
                            <tr key={item.id}>
                                <td className="item-cell">
                                    <span className="item-icon">{getItemIcon(item.item?.split(' ')[0])}</span>
                                    <span className="item-name">{item.item}</span>
                                </td>
                                <td>{item.worker}</td>
                                <td className="rfid-cell">{item.rut}</td>
                                <td className="time-cell">{item.timeAssign}</td>
                                <td className="time-cell">{item.timeReceive}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ScanHistory;

