source:
import { useState, useEffect, useRef } from "react";
import {
  scanTag,
  getReaderStatus,
  connectReader,
  registrarLectura,
  RFID_ROLES,
} from "../../services/rfidService";
import { searchEmployees } from "../../services/staffService";
import { huellasService } from "../../services/huellasService";
import "./ScanningPanel.css";

/**
 * Panel de escaneo RFID con soporte para dos lectores dedicados:
 *   - Modo "Recibir"  ÔåÆ usa el lector de Recepci├│n  (RFID_ROLES.RECEPTION)
 *   - Modo "Asignar"  ÔåÆ usa el lector de Asignaci├│n (RFID_ROLES.ASSIGNMENT)
 *
 * Si un lector falla, se muestra un banner de error espec├¡fico
 * sin bloquear el modo del otro lector.
 */
const ScanningPanel = ({ onScan, onWorkerSelect }) => {
  const [activeTab, setActiveTab] = useState("receive"); // 'receive' | 'assign'

  // Estado de conexi├│n del lector activo
  const [readerConnected, setReaderConnected] = useState(false);

  // Error de hardware espec├¡fico: { role, message } | null
  const [hardwareError, setHardwareError] = useState(null);

  // Estados para "Recibir prenda"
  const [status, setStatus] = useState("Buen Estado");
  const [notes, setNotes] = useState("");
  const [scanning, setScanning] = useState(false);
  const [lastScan, setLastScan] = useState(null);

  // Estados para "Asignar prenda"
  const [workerQuery, setWorkerQuery] = useState("");
  const [workerData, setWorkerData] = useState(null);
  const [isAssigning, setIsAssigning] = useState(false);
  const [assignedItems, setAssignedItems] = useState([]);
  const [searchError, setSearchError] = useState("");

  // Estados para "Recibir Prenda" (Bulk)
  const [scannedItemsReceive, setScannedItemsReceive] = useState([]);

  // Estados para identificaci├│n biom├®trica
  const [fpIdentifying, setFpIdentifying] = useState(false);
  const [fpSessionId, setFpSessionId] = useState(null);
  const [fpError, setFpError] = useState("");
  const [showManualSearch, setShowManualSearch] = useState(false);
  const fpPollingRef = useRef(null);

  const assignLoopRef = useRef(false);
  const receiveLoopRef = useRef(false);

  // Retorna el rol RFID correspondiente al tab activo
  const getActiveRole = (tab = activeTab) =>
    tab === "receive" ? RFID_ROLES.RECEPTION : RFID_ROLES.ASSIGNMENT;

  // Conecta el lector del rol indicado y actualiza el estado de conexi├│n
  const initReader = async (role) => {
    try {
      const result = await connectReader(role);
      setReaderConnected(result.conectado);
    } catch (error) {
      console.error(`Error al conectar lector (${role}):`, error);
      setReaderConnected(false);
    }
  };

  // Al montar: conectar el lector de recepci├│n (tab inicial)
  useEffect(() => {
    initReader(RFID_ROLES.RECEPTION);

    return () => {
      stopAssignLoop();
      receiveLoopRef.current = false;
    };
  }, []);

  // Al cambiar de tab: verificar estado del lector correspondiente
  useEffect(() => {
    const role = getActiveRole(activeTab);
    getReaderStatus(role)
      .then((result) => setReaderConnected(result.conectado))
      .catch(() => setReaderConnected(false));
    // Limpiar error de hardware al cambiar de tab
    setHardwareError(null);
  }, [activeTab]);

  // Manejador de teclado global para el panel
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.target.matches("input") || e.target.matches("textarea")) {
        return;
      }

      // --- MODO RECIBIR ---
      if (activeTab === "receive") {
        if (e.key === "Enter" && !scanning) {
          startReceiveLoop();
        }
        if (e.key === " " && scanning) {
          e.preventDefault();
          stopReceiveLoop();
        }
      }

      // --- MODO ASIGNAR ---
      if (activeTab === "assign") {
        if (e.key === "Escape" || e.key.toLowerCase() === "x") {
          handleExitAssignMode();
          return;
        }
        if (e.key === "Enter" && workerData && !isAssigning) {
          startAssignLoop();
        }
        if (e.key === " " && isAssigning) {
          e.preventDefault();
          stopAssignLoop();
          resetAssignState();
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [activeTab, workerData, isAssigning, scanning]);

  const checkReaderStatus = async () => {
    try {
      const result = await getReaderStatus(getActiveRole());
      setReaderConnected(result.conectado);
    } catch {
      setReaderConnected(false);
    }
  };

  const handleConnect = async () => {
    const role = getActiveRole();
    try {
      const result = await connectReader(role);
      setReaderConnected(result.conectado);
      if (result.conectado) setHardwareError(null);
    } catch (error) {
      console.error(`Error al conectar lector (${role}):`, error);
    }
  };

  const stopReceiveLoop = () => {
    setScanning(false);
    receiveLoopRef.current = false;
  };

  const stopAssignLoop = () => {
    setIsAssigning(false);
    assignLoopRef.current = false;
  };

  const resetAssignState = () => {
    setWorkerData(null);
    setWorkerQuery("");
    setAssignedItems([]);
  };

  const stopFpPolling = () => {
    if (fpPollingRef.current) {
      clearInterval(fpPollingRef.current);
      fpPollingRef.current = null;
    }
  };

  const handleExitAssignMode = () => {
    stopAssignLoop();
    stopFpPolling();
    setActiveTab("receive");
    resetAssignState();
    setFpIdentifying(false);
    setFpSessionId(null);
    setFpError("");
    setShowManualSearch(false);
  };

  /**
   * Maneja el error de hardware retornado por el backend.
   * Si hardware_error=true, muestra banner espec├¡fico y detiene el loop.
   * Retorna true si hubo error (el caller debe detenerse).
   */
  const handleHardwareError = (result, role) => {
    if (result.hardware_error) {
      const roleName =
        role === RFID_ROLES.RECEPTION
          ? `Recepci├│n (${role})`
          : `Asignaci├│n (${role})`;
      setHardwareError({
        role,
        message: `Error de Hardware: Lector de ${roleName} no disponible. Contacte a Soporte.`,
      });
      setReaderConnected(false);
      return true;
    }
    // Escaneo exitoso: limpiar error previo si exist├¡a
    setHardwareError(null);
    return false;
  };

  const scanReceiveLoop = async () => {
    if (!receiveLoopRef.current) return;

    try {
      const result = await scanTag(RFID_ROLES.RECEPTION);

      if (handleHardwareError(result, RFID_ROLES.RECEPTION)) {
        stopReceiveLoop();
        return;
      }

      if (result.encontrado && receiveLoopRef.current) {
        await registrarLectura({
          tag_epc: result.epc,
          accion: "RECEPCION",
          detalle: "Recepci├│n masiva de prendas",
        });

        setLastScan(result);
        onScan?.(result);

        setScannedItemsReceive((prev) => {
          if (prev.some((item) => item.epc === result.epc)) return prev;
          return [{ ...result, timestamp: new Date() }, ...prev];
        });

        setTimeout(scanReceiveLoop, 500);
      } else {
        if (receiveLoopRef.current) setTimeout(scanReceiveLoop, 500);
      }
    } catch (error) {
      console.error("Error scanning (receive):", error);
      if (receiveLoopRef.current) setTimeout(scanReceiveLoop, 1000);
    }
  };

  // --- L├│gica de Recibir Prenda (Bulk) ---
  // Usa el lector de Recepci├│n (RFID_ROLES.RECEPTION)

  const startReceiveLoop = async () => {
    if (!readerConnected) {
      await handleConnect();
    }
    setScanning(true);
    receiveLoopRef.current = true;
    setScannedItemsReceive([]);
    scanReceiveLoop();
  };

  const handleSearchWorker = async (e) => {
    e?.preventDefault();
    setSearchError("");
    if (!workerQuery.trim()) return;

    try {
      const cleanInput = workerQuery.replace(/[\.\-]/g, "");
      const response = await searchEmployees(cleanInput);
      const workers = response.data || response;

      if (Array.isArray(workers) && workers.length > 0) {
        setWorkerData(workers[0]);
        setSearchError("");
        onWorkerSelect?.(workers[0]);
      } else {
        setWorkerData(null);
        setSearchError("Trabajador no encontrado. Verifique el RUT.");
      }
    } catch (error) {
      console.error("Error buscando trabajador:", error);
      setSearchError("Error al buscar trabajador.");
    }
  };

  const scanForAssignment = async () => {
    if (!assignLoopRef.current) return;

    try {
      const result = await scanTag(RFID_ROLES.ASSIGNMENT);

      if (handleHardwareError(result, RFID_ROLES.ASSIGNMENT)) {
        stopAssignLoop();
        return;
      }

      if (result.encontrado && assignLoopRef.current) {
        await registrarLectura({
          tag_epc: result.epc,
          accion: "ASIGNACION",
          detalle: `Asignado a ${workerData.NombreCompleto || workerData.name} (${workerData.Rut || workerData.rut})`,
          rut: workerData.Rut || workerData.rut,
        });

        setAssignedItems((prev) => {
          if (prev.some((item) => item.epc === result.epc)) return prev;
          return [{ ...result, timestamp: new Date() }, ...prev];
        });

        setTimeout(scanForAssignment, 500);
      } else {
        if (assignLoopRef.current) setTimeout(scanForAssignment, 500);
      }
    } catch (error) {
      console.error("Error en loop de asignaci├│n:", error);
      if (assignLoopRef.current) setTimeout(scanForAssignment, 1000);
    }
  };

  const startAssignLoop = async () => {
    if (!readerConnected) {
      await handleConnect();
    }
    setIsAssigning(true);
    assignLoopRef.current = true;
    scanForAssignment();
  };

  // --- Identificaci├│n biom├®trica ---

  const handleFingerprintIdentify = async () => {
    setFpError("");
    setFpIdentifying(true);
    try {
      // El backend ahora gestiona la carga de templates autom├íticamente
      const { session_id } = await huellasService.iniciarIdentificacion();
      setFpSessionId(session_id);

      // Polling cada 500ms
      fpPollingRef.current = setInterval(async () => {
        try {
          const estado = await huellasService.obtenerEstado(session_id);

          if (estado.status === "completado") {
            stopFpPolling();
            setFpIdentifying(false);
            if (estado.resultado) {
              // Mapear resultado a formato de workerData
              const worker = {
                Rut: estado.resultado.rut,
                NombreCompleto: estado.resultado.nombre_completo,
                Cargo: estado.resultado.cargo,
                Empresa: estado.resultado.empresa,
              };
              setWorkerData(worker);
              onWorkerSelect?.(worker);
            } else {
              setFpError("Huella no reconocida. Intente nuevamente o use b├║squeda manual.");
            }
          } else if (estado.status === "error") {
            stopFpPolling();
            setFpIdentifying(false);
            setFpError(estado.error || "Error durante la identificaci├│n");
          } else if (estado.status === "cancelado") {
            stopFpPolling();
            setFpIdentifying(false);
          }
        } catch {
          stopFpPolling();
          setFpIdentifying(false);
          setFpError("Error de comunicaci├│n con el servidor");
        }
      }, 500);
    } catch (err) {
      setFpIdentifying(false);
      const msg = err?.response?.data?.detail || err.message || "Error al iniciar identificaci├│n";
      setFpError(msg);
    }
  };

  const handleCancelFingerprint = async () => {
    stopFpPolling();
    if (fpSessionId) {
      try { await huellasService.cancelarSesion(fpSessionId); } catch {}
    }
    setFpIdentifying(false);
    setFpSessionId(null);
  };

  return (
    <div className="scanning-panel-card">
      {/* Header */}
      <div className="panel-header">
        <div>
          <h3 className="panel-title">Panel de Escaneo</h3>
          <p className="panel-subtitle">
            Gestione la entrada y salida de prendas mediante RFID
          </p>
        </div>
      </div>

      <div className="panel-content">
        {/* Indicador de estado del lector activo */}
        <div
          className={`sensor-status ${readerConnected ? "" : "disconnected"}`}
          onClick={!readerConnected ? handleConnect : undefined}
          style={
            !readerConnected
              ? { cursor: "pointer", marginBottom: "1rem", gridColumn: "1 / -1" }
              : { marginBottom: "1rem", gridColumn: "1 / -1" }
          }
          title={!readerConnected ? "Haga clic para conectar" : ""}
        >
          <span className={`sensor-dot ${readerConnected ? "" : "off"}`}></span>
          {readerConnected
            ? `SENSOR ${activeTab === "receive" ? "RECEPCI├ôN" : "ASIGNACI├ôN"} ACTIVO`
            : `SENSOR DESCONECTADO ÔÇö clic para conectar`}
        </div>

        {/* Banner de error de hardware */}
        {hardwareError && (
          <div
            style={{
              gridColumn: "1 / -1",
              background: "#fee2e2",
              border: "1px solid #ef4444",
              borderRadius: "8px",
              padding: "0.75rem 1rem",
              marginBottom: "1rem",
              color: "#991b1b",
              fontSize: "0.875rem",
              fontWeight: 500,
            }}
          >
            ÔÜá {hardwareError.message}
            {hardwareError.role !== getActiveRole() && (
              <span style={{ display: "block", marginTop: "0.25rem", fontWeight: 400 }}>
                El lector del otro modo sigue disponible.
              </span>
            )}
          </div>
        )}

        {/* --- Tab: Recibir Prenda --- */}
        {activeTab === "receive" && (
          <div className="receive-mode-container">
            <div className="bulk-scan-controls">
              <div className="main-actions-row">
                {!scanning ? (
                  <button className="bulk-receive-btn start" onClick={startReceiveLoop}>
                    <span></span> RECIBIR PRENDAS
                  </button>
                ) : (
                  <button className="bulk-receive-btn stop" onClick={stopReceiveLoop}>
                    <span></span> DETENER RECEPCI├ôN
                  </button>
                )}

                <button
                  className="bulk-receive-btn assign-action"
                  onClick={() => setActiveTab("assign")}
                  disabled={scanning}
                >
                  <span></span> ASIGNAR PRENDA
                </button>
              </div>

              <p className="hint-text">
                {scanning
                  ? `Recibiendo prendas... Total: ${scannedItemsReceive.length}. Presione 'Detener' para finalizar.`
                  : "Modo Recepci├│n: Las prendas detectadas se registrar├ín con su fecha de devoluci├│n."}
              </p>
            </div>

            <div className="scanned-items-list">
              <div className="items-scroll">
                {scannedItemsReceive.map((item, idx) => (
                  <div key={idx} className="scanned-item-row">
                    <span>Ô£à {item.sku || "Desconocido"}</span>
                    <small>{item.epc}</small>
                  </div>
                ))}
                {scannedItemsReceive.length === 0 && (
                  <p className="empty-list">Ninguna prenda detectada a├║n.</p>
                )}
              </div>
            </div>
          </div>
        )}

        {/* --- Tab: Asignar Prenda --- */}
        {activeTab === "assign" && (
          <div className="assign-mode-container">
            <button
              className="close-assign-btn"
              onClick={handleExitAssignMode}
              title="Salir (X)"
            >
              Ô£û
            </button>

            {!workerData ? (
              <div className="worker-search-view">
                <h4>Asignaci├│n de Prendas</h4>
                <p>Identifique al trabajador para comenzar.</p>

                {/* Identificaci├│n biom├®trica */}
                {!showManualSearch && (
                  <div className="fp-identify-section">
                    {!fpIdentifying ? (
                      <button
                        className="fp-identify-btn"
                        onClick={handleFingerprintIdentify}
                        disabled={fpIdentifying}
                      >
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginRight: '0.5rem' }}>
                          <path d="M12 10a2 2 0 00-2 2c0 1.02.76 2 2 2s2-.98 2-2a2 2 0 00-2-2z"/>
                          <path d="M12 2C9.24 2 7 4.24 7 7v2a5 5 0 0010 0V7c0-2.76-2.24-5-5-5z"/>
                          <path d="M17 13a5 5 0 01-10 0"/>
                        </svg>
                        Identificar con Huella
                      </button>
