const TabCatalogo = ({ titulo, idKey, nombreKey, fetchFn, createFn, updateFn, deleteFn, onCatalogoChange }) => {
    const [items, setItems] = useState([]);
    const [loading, setLoading] = useState(true);

    const [modalAbierto, setModalAbierto] = useState(false);
    const [itemEditando, setItemEditando] = useState(null);
    const [guardando, setGuardando] = useState(false);
    const [errorModal, setErrorModal] = useState('');

    const [itemEliminando, setItemEliminando] = useState(null);
    const [eliminando, setEliminando] = useState(false);
    const [errorEliminar, setErrorEliminar] = useState('');

    const cargar = useCallback(async () => {
        setLoading(true);
        try {
            const data = await fetchFn();
            setItems(data);
            onCatalogoChange?.();
        } catch {
            setItems([]);
        } finally {
            setLoading(false);
        }
    }, [fetchFn]);

    useEffect(() => { cargar(); }, [cargar]);

    const abrirCrear = () => {
        setItemEditando(null);
        setErrorModal('');
        setModalAbierto(true);
    };

    const abrirEditar = (item) => {
        setItemEditando(item);
        setErrorModal('');
        setModalAbierto(true);
    };

    const cerrarModal = () => {
        if (guardando) return;
        setModalAbierto(false);
        setItemEditando(null);
        setErrorModal('');
    };

    const handleGuardar = async (nombre) => {
        setGuardando(true);
        setErrorModal('');
        try {
            if (itemEditando) {
                await updateFn(itemEditando[idKey], nombre);
            } else {
                await createFn(nombre);
            }
            setModalAbierto(false);
            setItemEditando(null);
            await cargar();
        } catch (err) {
            setErrorModal(err.message || 'Error al guardar');
        } finally {
            setGuardando(false);
        }
    };

    const abrirConfirmEliminar = (item) => {
        setItemEliminando(item);
        setErrorEliminar('');
    };

    const cerrarConfirmEliminar = () => {
        if (eliminando) return;
        setItemEliminando(null);
        setErrorEliminar('');
    };

    const handleEliminar = async () => {
        setEliminando(true);
        setErrorEliminar('');
        try {
            await deleteFn(itemEliminando[idKey]);
            setItemEliminando(null);
            await cargar();
        } catch (err) {
            setErrorEliminar(err.message || 'Error al eliminar');
        } finally {
            setEliminando(false);
        }
    };

    return (
        <>
            <div className="catalogo-tab-header">
                <h3 className="catalogo-tab-title">{titulo}</h3>
                <button className="catalogo-btn catalogo-btn--primary" onClick={abrirCrear}>
                    + Agregar
                </button>
            </div>

            <CatalogoTable
                items={items}
                idKey={idKey}
                nombreKey={nombreKey}
                onEditar={abrirEditar}
                onEliminar={abrirConfirmEliminar}
                loading={loading}
            />

            {modalAbierto && (
                <CatalogoModal
                    titulo={itemEditando ? `Editar ${titulo}` : `Nuevo ${titulo}`}
                    valorInicial={itemEditando ? itemEditando[nombreKey] : ''}
                    onGuardar={handleGuardar}
                    onCerrar={cerrarModal}
                    guardando={guardando}
                    errorServidor={errorModal}
                />
            )}

            {itemEliminando && (
                <ConfirmDeleteModal
                    mensaje={`┬┐Eliminar "${itemEliminando[nombreKey]}"? Esta acci├│n no se puede deshacer.`}
                    errorServidor={errorEliminar}
                    onConfirmar={handleEliminar}
                    onCerrar={cerrarConfirmEliminar}
                    eliminando={eliminando}
                />
            )}
        </>
    );
};

