            setTiposMap(Object.fromEntries(tiposData.map((t) => [t.TipoID, t.nombreTipo])));
            setTallasMap(Object.fromEntries(tallasData.map((t) => [t.TallaID, t.nombreTalla])));
        } catch {
            // silencioso, IDs como fallback
        }
    }, []);

    useEffect(() => { cargarMapas(); }, [cargarMapas]);

    const tabs = [
        { id: 'prendas',   label: 'Prendas' },
        { id: 'tipos',     label: 'Tipos de prenda' },
        { id: 'tallas',    label: 'Tallas' },
