            )}

            {activeTab === 'tallas' && (
                <TabCatalogo
                    titulo="Talla"
                    idKey="TallaID"
                    nombreKey="nombreTalla"
                    fetchFn={getTallas}
                    createFn={createTalla}
                    updateFn={updateTalla}
                    deleteFn={deleteTalla}
                    onCatalogoChange={cargarMapas}
                />
            )}

            {/* Tab de inventario RFID ÔÇö siempre montado para poder hacer cleanup on tab change */}
            <div style={{ display: activeTab === 'inventario-rfid' ? 'block' : 'none' }}>
                <TabRealizarInventario
