    const timeoutRef = useRef(null);

    useEffect(() => {
        checkReader();
        fetchCatalogos();
        checkEstadoSesion();
        return () => {
            stopPolling();
        };
    }, []);

    const fetchCatalogos = async () => {
        try {
            const [tiposData, tallasData] = await Promise.all([
                apiClient.get('/inventario/tipos'),
                apiClient.get('/inventario/tallas'),
            ]);
            setTipos(tiposData);
            setTallas(tallasData);
        } catch (err) {
            console.error('Error al cargar cat├ílogos:', err);
        }
    };

    const checkReader = async () => {
        try {
            const status = await getReaderStatus();
            setReaderConnected(status.conectado);
        } catch {
            setReaderConnected(false);
        }
    };

    const checkEstadoSesion = async () => {
        try {
            const estado = await getEstadoModoInventario();
            if (estado.activo) {
                setSesionActiva(true);
                setTipoNombre(estado.tipo_nombre || '');
                setTallaNombre(estado.talla_nombre || '');
                isStopping.current = false;
                startPolling();
            }
        } catch {
            // sesi├│n no activa
        }
    };

    const handleConnect = async () => {
        try {
            const result = await connectReader();
            setReaderConnected(result.conectado);
        } catch {
            alert('No se pudo conectar al lector RFID.');
        }
    };

    const doScan = useCallback(async () => {
        if (isStopping.current) return;

        try {
            const result = await scanModoInventario();

            // Si el modo se detuvo mientras la petici├│n estaba en vuelo, ignoramos
            if (isStopping.current) return;

            if (result.encontrado) {
                if (result.duplicado) {
                    setDuplicados(prev => prev + 1);
                } else {
                    // Nuevo EPC registrado
                    setPrendasLeidas(prev => [{
                        sku: result.sku,
                        epc: result.epc,
                        tipo_prenda: result.tipo_prenda,
                        talla: result.talla,
                        hora: new Date().toLocaleTimeString(),
                    }, ...prev]);
                }
            }
        } catch (err) {
            console.error('Error en scan:', err);
            // Si el modo se detuvo externamente
            if (err.message?.includes('no est├í activo')) {
                setSesionActiva(false);
                stopPolling();
                return;
            }
        }

        // Programar siguiente lectura si seguimos activos
        if (!isStopping.current) {
            timeoutRef.current = setTimeout(doScan, SCAN_INTERVAL_MS);
        }
    }, []);

    const startPolling = useCallback(() => {
        stopPolling();
        isStopping.current = false;
        timeoutRef.current = setTimeout(doScan, SCAN_INTERVAL_MS);
    }, [doScan]);

    const stopPolling = () => {
        isStopping.current = true;
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
            timeoutRef.current = null;
        }
    };

    const handleIniciar = async () => {
        if (!tipoId || !tallaId) {
            setError('Seleccione categor├¡a y talla antes de iniciar.');
            return;
        }
        setError(null);
        setLoading(true);

        try {
            const estado = await iniciarModoInventario(parseInt(tipoId), parseInt(tallaId));
            setSesionActiva(true);
            setTipoNombre(estado.tipo_nombre || '');
            setTallaNombre(estado.talla_nombre || '');
            setPrendasLeidas([]);
            setDuplicados(0);
            startPolling();
        } catch (err) {
            setError(err.message || 'Error al iniciar modo inventario.');
        } finally {
            setLoading(false);
        }
    };

    const handleDetener = async () => {
        setLoading(true);
        // Detenemos el polling DE INMEDIATO visualmente
        stopPolling();

        try {
            const resumen = await detenerModoInventario();
            setSesionActiva(false);
            alert(`Modo inventario detenido. Se registraron ${resumen.cantidad_registrada} prenda(s).`);
        } catch (err) {
            setError(err.message || 'Error al detener modo inventario.');
            // Si fall├│, quiz├ís sigue activo, pero mejor forzar parada local
            setSesionActiva(false);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="page-container">
            <div className="inventory-header">
                <div>
                    <h2 className="inventory-title">Modo Inventario RFID</h2>
                    <p className="inventory-subtitle">
                        Lectura continua para registro masivo de prendas
                    </p>
                </div>
                <div className="inventory-actions">
                    <div
                        className={`reader-indicator ${readerConnected ? 'connected' : ''}`}
                        onClick={!readerConnected ? handleConnect : undefined}
                        style={!readerConnected ? { cursor: 'pointer' } : {}}
                        title={!readerConnected ? 'Clic para conectar' : 'Lector conectado'}
                    >
                        <span className={`reader-dot ${readerConnected ? 'on' : ''}`}></span>
                        {readerConnected ? 'Lector RFID Activo' : 'Lector Desconectado'}
                    </div>
                </div>
            </div>

            {error && (
                <div className="im-error">
                    {error}
                    <button className="im-error-close" onClick={() => setError(null)}>x</button>
                </div>
            )}

            {/* Panel de control */}
            <div className="im-control-panel">
                <div className="im-selectors">
                    <div className="im-field">
                        <label className="im-label">Categor├¡a</label>
                        <select
                            className="im-select"
                            value={tipoId}
                            onChange={(e) => setTipoId(e.target.value)}
                            disabled={sesionActiva}
                        >
                            <option value="">Seleccionar categor├¡a...</option>
                            {tipos.map((t) => (
                                <option key={t.TipoID} value={t.TipoID}>
                                    {t.nombreTipo}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="im-field">
                        <label className="im-label">Talla</label>
                        <select
                            className="im-select"
                            value={tallaId}
                            onChange={(e) => setTallaId(e.target.value)}
                            disabled={sesionActiva}
                        >
                            <option value="">Seleccionar talla...</option>
                            {tallas.map((t) => (
                                <option key={t.TallaID} value={t.TallaID}>
                                    {t.nombreTalla}
                                </option>
                            ))}
                        </select>
                    </div>
                </div>
                <div className="im-buttons">
                    {!sesionActiva ? (
                        <button
                            className="im-btn im-btn-start"
                            onClick={handleIniciar}
                            disabled={loading || !readerConnected}
                        >
                            {loading ? 'Iniciando...' : 'Iniciar Inventario'}
                        </button>
                    ) : (
                        <button
                            className="im-btn im-btn-stop"
                            onClick={handleDetener}
                            disabled={loading}
                        >
                            {loading ? 'Deteniendo...' : 'Detener Inventario'}
                        </button>
                    )}
                </div>
            </div>

            {/* Estado de sesi├│n activa */}
            {sesionActiva && (
                <div className="im-session-info">
                    <div className="im-session-badge">
                        <span className="im-pulse-dot"></span>
                        Modo Inventario Activo
                    </div>
                    <div className="im-session-details">
                        <span>Categor├¡a: <strong>{tipoNombre}</strong></span>
                        <span>Talla: <strong>{tallaNombre}</strong></span>
                        <span>Registradas: <strong>{prendasLeidas.length}</strong></span>
                        <span>Duplicados ignorados: <strong>{duplicados}</strong></span>
                    </div>
                </div>
            )}

            {/* Tabla de chips le├¡dos */}
            {prendasLeidas.length > 0 ? (
                <div className="inventory-table-container">
                    <table className="inventory-table">
                        <thead>
                            <tr>
                                <th>#</th>
                                <th>SKU</th>
                                <th>EPC</th>
                                <th>CATEGOR├ìA</th>
                                <th>TALLA</th>
                                <th>HORA</th>
                            </tr>
                        </thead>
                        <tbody>
                            {prendasLeidas.map((p, idx) => (
                                <tr key={p.epc} className={idx === 0 ? 'im-new-row' : ''}>
                                    <td>{prendasLeidas.length - idx}</td>
                                    <td className="sku-cell">{p.sku}</td>
                                    <td className="epc-cell">{p.epc}</td>
                                    <td>{p.tipo_prenda}</td>
                                    <td>{p.talla}</td>
                                    <td>{p.hora}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            ) : sesionActiva ? (
                <div className="page-placeholder">
                    <div className="placeholder-icon">­ƒôí</div>
                    <h2 className="placeholder-title">Esperando lecturas...</h2>
                    <p className="placeholder-text">
                        Acerque las prendas al lector RFID. Los chips detectados aparecer├ín aqu├¡ autom├íticamente.
                    </p>
                </div>
            ) : (
                <div className="page-placeholder">
                    <div className="placeholder-icon">­ƒÅÀ´©Å</div>
                    <h2 className="placeholder-title">Modo Inventario</h2>
                    <p className="placeholder-text">
                        Seleccione una categor├¡a y talla, luego presione "Iniciar Inventario" para comenzar la lectura continua de chips RFID.
                    </p>
                </div>
            )}
        </div>
    );
};

