import { useState, useEffect } from 'react';
import FileUploadArea from '../components/reports/FileUploadArea';
import ReportGenerator from '../components/reports/ReportGenerator';
import RecentExportsTable from '../components/reports/RecentExportsTable';
import {
    uploadBulkData,
    downloadTemplate,
    generateReport,
    getRecentExports,
    downloadExport
} from '../services/reportsService';
import './Reports.css';

const Reports = () => {
    const [exports, setExports] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadExports();
    }, []);

    const loadExports = async () => {
        try {
            setLoading(true);
            const response = await getRecentExports(1, 10);
            setExports(response.data);
        } catch (error) {
            console.error('Error loading exports:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleFileUpload = async (file, templateId) => {
        const result = await uploadBulkData(file, templateId);
        return result;
    };

    const handleTemplateDownload = async () => {
        await downloadTemplate('stock');
    };

    const handleGenerate = async (config) => {
        const fullConfig = { ...config, format: 'pdf' };
        const result = await generateReport(fullConfig);
        alert(result.message);
        await loadExports();
    };

    const handleExportPDF = async (config) => {
        const fullConfig = { ...config, format: 'pdf' };
        const result = await generateReport(fullConfig);
        alert('Reporte PDF generado exitosamente');
        await loadExports();
    };

    const handleExportExcel = async (config) => {
        const fullConfig = { ...config, format: 'excel' };
        const result = await generateReport(fullConfig);
        alert('Reporte Excel generado exitosamente');
        await loadExports();
    };

    const handleDownload = async (exportId) => {
        try {
            await downloadExport(exportId);
        } catch (error) {
            console.error('Download error:', error);
            alert(error.message || 'Error al descargar el archivo');
        }
    };

    return (
        <div className="reports-page">
            <div className="reports-header">
                <div>
                    <h1 className="reports-title">Reportes y Gesti├│n de Datos</h1>
                    <p className="reports-subtitle">
                        Importe datos de inventario masivos o genere reportes detallados de equipos para cumplimiento y auditor├¡a.
                    </p>
                </div>
            </div>

            <div className="reports-grid">
                <FileUploadArea
                    onFileUpload={handleFileUpload}
                    onTemplateDownload={handleTemplateDownload}
                />

                <ReportGenerator
                    onGenerate={handleGenerate}
                    onExportPDF={handleExportPDF}
                    onExportExcel={handleExportExcel}
                />
            </div>

            <RecentExportsTable
                exports={exports}
                onDownload={handleDownload}
                loading={loading}
            />
        </div>
    );
};

export default Reports;

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import WorkerLayout from '../components/worker/WorkerLayout';
import WorkerProfile from '../components/worker/WorkerProfile';
import BiometricScanner from '../components/worker/BiometricScanner';
import ScanningPanel from '../components/worker/ScanningPanel';
import ScanHistory from '../components/worker/ScanHistory';
import { apiClient } from '../services/api';
import './WorkerDashboard.css';

const WorkerDashboard = () => {
    const { user } = useAuth();
    const [scanHistory, setScanHistory] = useState([]);
    const [loading, setLoading] = useState(true);

    // Estado para el perfil del trabajador seleccionado en "Asignar"
    const [selectedWorker, setSelectedWorker] = useState(null);

    const fetchScanHistory = useCallback(async () => {
        try {
            setLoading(true);
            // Obtener asignaciones en lugar de log crudo
            const response = await apiClient.get('/asignaciones/todas');
            const data = response.data || [];

            const mapped = data.map((asig) => ({
                id: asig.AsignacionID,
                item: asig.Item || asig.SKU, // "Item" viene del join en backend
                rfid: asig.SKU, // SKU como identificador visual secundario
                worker: asig.NombreCompleto,
                rut: asig.Rut,
                status: asig.FechaDevolucion ? 'Entregado' : 'Asignado',
                timeAssign: new Date(asig.FechaEntrega).toLocaleTimeString(),
                timeReceive: asig.FechaDevolucion ? new Date(asig.FechaDevolucion).toLocaleTimeString() : '--',
            }));
            setScanHistory(mapped);
        } catch (error) {
            console.error('Error al cargar historial de asignaciones:', error);
            setScanHistory([]);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchScanHistory();
    }, [fetchScanHistory]);

    // Perfil visual: Usa el seleccionado, o falla al usuario logueado/default
    const workerProfile = {
        id: selectedWorker?.Rut || user?.id || 'EMP-000',
        name: selectedWorker?.NombreCompleto || user?.name || 'Esperando trabajador...',
        department: selectedWorker?.Area || user?.department || '--',
        shift: selectedWorker?.Cargo || user?.shift || '--',
        zone: selectedWorker?.Empresa || user?.zone || '--',
        status: 'ACTIVO',
        avatar: user?.avatar,
    };

    const handleScan = async (scanResult) => {
        console.log('Scan result:', scanResult);
        // Refrescar historial tras un escaneo exitoso
        await fetchScanHistory();
    };

    const handleWorkerSelect = (worker) => {
        setSelectedWorker(worker);
    };

    const handleBiometricVerify = (data) => {
        console.log('Biometric verify:', data);
    };

    const handleEditItem = (item) => {
        console.log('Edit item:', item);
        alert(`Editando: ${item.item} (${item.rfid})`);
    };

    return (
        <WorkerLayout>
            <div className="worker-dashboard">
                <div className="dashboard-left">
                    <WorkerProfile worker={workerProfile} />
                    {/* <BiometricScanner onVerify={handleBiometricVerify} /> */}
                </div>

                <div className="dashboard-right">
                    <ScanningPanel onScan={handleScan} onWorkerSelect={handleWorkerSelect} />
                    <ScanHistory
                        items={scanHistory}
                        onEdit={handleEditItem}
                        loading={loading}
                    />
                </div>
            </div>
        </WorkerLayout>
    );
};

export default WorkerDashboard;

