  // Polling: obtener estado de una sesi├│n ÔÇö redireccionado al backend
  obtenerEstado: async (sessionId) => {
    return await apiClient.get(`/biometria/estado/${sessionId}`);
  },

  // Cancelar sesi├│n activa ÔÇö redireccionado al backend
  cancelarSesion: async (sessionId) => {
    return await apiClient.post(`/biometria/cancelar/${sessionId}`);
  },

